<?php
require_once __DIR__.'/../includes/bootstrap.php';
try {
    $db=fleet_db();
    $export=(string)($_GET['export']??'')==='1';
    $base="SELECT h.changed_at AS event_at,CONVERT(COALESCE(u.full_name,'System import (user not recorded)') USING utf8mb4) COLLATE utf8mb4_unicode_ci AS actor,CONVERT(CONCAT(a.primary_identifier,' (',t.type_name,')') USING utf8mb4) COLLATE utf8mb4_unicode_ci AS record_name,CONVERT(CASE WHEN h.change_origin='INITIAL_IMPORT' THEN 'CREATE' ELSE 'UPDATE' END USING utf8mb4) COLLATE utf8mb4_unicode_ci AS event_type,CONVERT(h.field_name USING utf8mb4) COLLATE utf8mb4_unicode_ci AS action,CONVERT(h.old_value USING utf8mb4) COLLATE utf8mb4_unicode_ci AS old_value,CONVERT(h.new_value USING utf8mb4) COLLATE utf8mb4_unicode_ci AS new_value,CONVERT(h.change_origin USING utf8mb4) COLLATE utf8mb4_unicode_ci AS source FROM asset_change_history h JOIN assets a ON a.id=h.asset_id JOIN asset_types t ON t.id=a.asset_type_id LEFT JOIN users u ON u.id=h.changed_by UNION ALL SELECT l.created_at,CONVERT(COALESCE(u.full_name,'System / unassigned') USING utf8mb4) COLLATE utf8mb4_unicode_ci,CONVERT(CONCAT(COALESCE(l.entity_type,'record'),' #',COALESCE(l.entity_id,'')) USING utf8mb4) COLLATE utf8mb4_unicode_ci,CONVERT(l.action_type USING utf8mb4) COLLATE utf8mb4_unicode_ci,CONVERT(l.action_type USING utf8mb4) COLLATE utf8mb4_unicode_ci,CONVERT(NULL USING utf8mb4) COLLATE utf8mb4_unicode_ci,CONVERT(l.description USING utf8mb4) COLLATE utf8mb4_unicode_ci,CONVERT('ACTIVITY_LOG' USING utf8mb4) COLLATE utf8mb4_unicode_ci FROM activity_logs l LEFT JOIN users u ON u.id=l.user_id";
    $sql='SELECT * FROM ('.$base.') audit_rows';$params=[];$search=trim((string)($_GET['q']??''));if($search!==''){$sql.=" WHERE CONCAT_WS(' ',actor,record_name,event_type,action,old_value,new_value,source) LIKE ?";$params[]='%'.$search.'%';}$sql.=' ORDER BY event_at DESC'.($export?'':' LIMIT ?');$q=$db->prepare($sql);foreach($params as $i=>$param)$q->bindValue($i+1,$param);if(!$export)$q->bindValue(count($params)+1,1000,PDO::PARAM_INT);$q->execute();
    json_response(['ok'=>true,'items'=>$q->fetchAll(),'note'=>'Imported records without a named user are labeled System / unassigned; user attribution is shown only when recorded.']);
}catch(Throwable $e){error_log('Fleet audit trail: '.$e->getMessage());json_response(['ok'=>false,'message'=>'Audit history could not be loaded.'],500);}
